package com.bank.internals.service;

import com.bank.internals.model.SessionToken;
import com.bank.internals.model.Transaction;
import com.bank.internals.repository.SessionTokenRepository;
import com.bank.internals.repository.TransactionRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;

@Service
public class StatementService {
    private static final Logger log = LoggerFactory.getLogger(StatementService.class);
    private final TransactionRepository txnRepo;
    private final SessionTokenRepository tokenRepo;

    public StatementService(TransactionRepository txnRepo, SessionTokenRepository tokenRepo) {
        this.txnRepo = txnRepo;
        this.tokenRepo = tokenRepo;
    }

    // B+tree range scan
    public List<Transaction> quarterlyStatement(String accountId,
                                                 LocalDateTime from, LocalDateTime to) {
        log.info("B+tree RANGE scan: account {} from {} to {}", accountId, from, to);
        return txnRepo.findByAccountIdAndCreatedAtBetween(accountId, from, to);
    }

    // Hash index point lookup
    public Optional<SessionToken> validateToken(String token) {
        log.info("Hash EXACT-MATCH lookup for token prefix {}...", token.substring(0, 6));
        return tokenRepo.findByToken(token);
    }
}
